using DaqqaTid.Infrastructure;
using Microsoft.AspNetCore.Identity;
using Xunit;

namespace DaqqaTid.UnitTests;

public sealed class CloudflarePasswordCompatibilityTests
{
    [Fact]
    public void Cloudflare_identity_v3_password_hash_is_accepted_by_the_Azure_backend()
    {
        // Generated by the actual Cloudflare hasher with a deterministic test-only salt.
        const string encodedHash = "AQAAAAIAAYagAAAAEAABAgMEBQYHCAkKCwwNDg9gCGUeHUoKYIJYMKBGgPKfmGVtN7rWUAXy9bnmzpeoZA==";
        var hasher = new PasswordHasher<ApplicationUser>();
        Assert.NotEqual(PasswordVerificationResult.Failed, hasher.VerifyHashedPassword(new ApplicationUser(), encodedHash, "Good-Password-2026"));
        Assert.Equal(PasswordVerificationResult.Failed, hasher.VerifyHashedPassword(new ApplicationUser(), encodedHash, "Wrong-Password-2026"));
    }
}
